 // One bounded retirement migration; never rewrite cards inside a running battle.
 function migrateRetired(p){
  const old='TW43-M07',replacement='TW43-M03';if(!cards[replacement]||!obj(p.collection))return p;
  let changed=false,refilled=0;const restarted=[];
  const hasOld=x=>x!==undefined&&JSON.stringify(x).includes('"'+old+'"');
  function mergeCounts(c){if(!obj(c)||!Object.hasOwn(c,old))return;const n=c[old],existing=c[replacement]||0;if(!integer(n)||n>9999||!integer(existing)||existing>19998||n+existing>19998)fail('INVALID_PROFILE','舊卡收藏張數不合法');c[replacement]=existing+n;delete c[old];changed=true;}
  mergeCounts(p.collection);
  function recipe(r){if(!obj(r)||!Array.isArray(r.main)||!Array.isArray(r.extra)||!hasOld(r))return;changed=true;const wanted=r.main.length;r.main=r.main.map(id=>id===old?replacement:id);r.extra=r.extra.map(id=>id===old?replacement:id);let seen=0;r.main=r.main.filter(id=>id!==replacement||++seen<=3);const used={};for(const id of [...r.main,...r.extra]){const name=cards[id]?.name||id;used[name]=(used[name]||0)+1;}
   const owned={};for(const id of [...r.main,...r.extra])owned[id]=(owned[id]||0)+1;
   const pool=[...new Set([...r.main,...(catalog.heroes?.[p.country]?.recipe?.main||[]),...Object.keys(p.collection).sort()])];
   for(const id of pool){const c=cards[id];if(!c||/fusion|synchro/.test(c.subtype||''))continue;const cap=Math.min(3,c.maxCopies??c.cardmax??3);while(r.main.length<wanted&&(owned[id]||0)<p.collection[id]&&(used[c.name]||0)<cap){r.main.push(id);owned[id]=(owned[id]||0)+1;used[c.name]=(used[c.name]||0)+1;refilled++;}if(r.main.length===wanted)break;}
  }
  recipe(p.activeRecipe);recipe(p.draftRecipe);if(Array.isArray(p.deckSlots))for(const slot of p.deckSlots){recipe(slot.recipe);recipe(slot.draft);}
  if(obj(p.run)){
   const r=p.run,affected=hasOld(r.state)||hasOld(r.config?.playerRecipe)||hasOld(r.config?.enemyRecipe);
   recipe(r.config?.playerRecipe);if(r.config?.enemyRecipe&&hasOld(r.config.enemyRecipe)){const current=catalog.heroes?.[r.config.enemy]?.recipe;if(current)r.config.enemyRecipe=clone(current);}
   for(const reward of [r.reward,r.rewardPlan?.first,r.rewardPlan?.repeat])mergeCounts(reward?.cards);
   if(affected){changed=true;r.state=null;if(r.status==='active'){r.restartNote='角色更新：本場將從開局重新開始，既有通關與獎勵保留。';restarted.push('九國巡禮');}}
  }
  for(const route of Object.values(storyRoutes))if(obj(p[route.key]?.run)){
   const r=p[route.key].run,affected=hasOld(r.state)||(!r.state&&hasOld(r.recipe));recipe(r.recipe);
   if(affected){changed=true;r.state=null;if(r.status==='active'){r.restartNote='角色更新：本章對局將從開局重新開始，已完成章節與獎勵保留。';restarted.push('故事第'+r.chapterId.slice(1)+'章');}}
  }
  if(changed){const recipes=[p.activeRecipe,p.run?.config?.playerRecipe,...Object.values(storyRoutes).map(route=>p[route.key]?.run?.recipe)].filter(Boolean),needsDeckRepair=recipes.some(r=>Array.isArray(r.main)&&r.main.length<40);
   p.cardMigration={version:1,needsDeckRepair,restarted,refilled,note:'朱一貴已由廖添丁取代；收藏張數已合併，同名出戰最多3張。'+(refilled?'超額位置已以持有卡片補足。':'')+(restarted.length?'受影響的'+restarted.join('、')+'將重新開局，既有進度與獎勵保留。':'')+(needsDeckRepair?'持有卡片不足以組成40張合法牌組，請先在卡庫調整，或選擇恢復主角標準牌組。':'')};
  }
  return p;
 }
